/**
 * Capability probe for dashboard_pro Summary.
 *
 * A public deployment may only have GPX (no HR, no training load, no per-second
 * streams). Every analysis block declares the tier it needs; missing data hides
 * the block instead of rendering an empty shell or a fake zero.
 *
 * Tiers (data flows in from `public/summary/aggregates.json`, generated by
 * `run_page/gen_summary.py`; absent file simply means L0-only):
 *
 *   L0  activities.json      date / distance / moving_time / type
 *   L1  activities.json      average_heartrate / elevation_gain
 *   L2  splits.summary       training_load / aerobic_te / vo2max / cadence ...
 *   L3  splits.zones         time in HR / pace / power zones
 *   L4  splits.chart         per-sample pace / hr / cad streams
 */

export type CapabilityKey =
  | 'hr' // any average_heartrate present
  | 'elevation'
  | 'trainingLoad'
  | 'aerobicTe'
  | 'vo2max'
  | 'cadence'
  | 'groundContact'
  | 'power'
  | 'hrZones'
  | 'paceZones'
  | 'streams' // per-sample chart data
  | 'splitDetails'; // per-km splits

export type Capabilities = Record<CapabilityKey, number>;

export const EMPTY_CAPABILITIES: Capabilities = {
  hr: 0,
  elevation: 0,
  trainingLoad: 0,
  aerobicTe: 0,
  vo2max: 0,
  cadence: 0,
  groundContact: 0,
  power: 0,
  hrZones: 0,
  paceZones: 0,
  streams: 0,
  splitDetails: 0,
};

/** Minimum sample size before a chart is worth drawing. */
export const MIN_SAMPLES = 3;

export type GateResult = 'hide' | 'insufficient' | 'show';

/** `all` (default) = every key must have samples; `any` = one is enough. */
export type GateMode = 'all' | 'any';

/**
 * Decide how a block should render.
 * - `hide`: feature absent everywhere (public GPX-only site)
 * - `insufficient`: some data, too little to chart — show a quiet note
 * - `show`: enough coverage
 *
 * `mode: 'any'` is for composite cards that draw each series independently
 * (e.g. AerobicTrend renders VO2max / decoupling / cadence separately), where
 * requiring every capability would hide the whole card just because one of them
 * is missing.
 */
export function gate(
  caps: Capabilities | null,
  need: CapabilityKey | CapabilityKey[],
  mode: GateMode = 'all'
): GateResult {
  if (!caps) return 'hide';
  const keys = Array.isArray(need) ? need : [need];
  if (mode === 'any') {
    const coveredAny = Math.max(...keys.map((k) => caps[k] ?? 0));
    if (coveredAny <= 0) return 'hide';
    return coveredAny >= MIN_SAMPLES ? 'show' : 'insufficient';
  }
  // Every required capability must have at least one sample.
  if (keys.some((k) => (caps[k] ?? 0) <= 0)) return 'hide';
  const covered = Math.min(...keys.map((k) => caps[k] ?? 0));
  return covered >= MIN_SAMPLES ? 'show' : 'insufficient';
}

/** Build capabilities from raw activities alone (L0/L1 — always available). */
export function capabilitiesFromActivities(
  activities: {
    average_heartrate?: number | null;
    elevation_gain?: number | null;
  }[]
): Capabilities {
  const caps = { ...EMPTY_CAPABILITIES };
  for (const a of activities) {
    if ((a.average_heartrate ?? 0) > 0) caps.hr += 1;
    if (a.elevation_gain != null) caps.elevation += 1;
  }
  return caps;
}

/** Merge split-derived coverage (L2–L4) over the activity-derived baseline. */
export function mergeCapabilities(
  base: Capabilities,
  extra: Partial<Capabilities> | null
): Capabilities {
  if (!extra) return base;
  const out = { ...base };
  for (const key of Object.keys(extra) as CapabilityKey[]) {
    out[key] = Math.max(out[key] ?? 0, extra[key] ?? 0);
  }
  return out;
}
